<?php require __DIR__.'/_layout_start.php'; ?><h1><?= (int)$row['id']?'Modifica album':'Nuovo album' ?></h1><?php foreach($errors as $er): ?><div class="error"><?= htmlspecialchars($er) ?></div><?php endforeach; ?><form method="post" enctype="multipart/form-data" action="/admin/content/gallery/save"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div class="formgrid"><label>Titolo<input name="title" value="<?= htmlspecialchars($row['title']) ?>" required></label><label>Slug<input name="slug" value="<?= htmlspecialchars($row['slug']) ?>"></label><label class="full">Descrizione<textarea name="description" rows="5"><?= htmlspecialchars((string)$row['description']) ?></textarea></label><label>Copertina<input type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($row['cover_image'])): ?><small>Attuale: <?= htmlspecialchars($row['cover_image']) ?></small><?php endif; ?></label><label>Ordine<input type="number" name="sort_order" value="<?= (int)$row['sort_order'] ?>"></label><label class="check"><input type="checkbox" name="published" value="1" <?= !empty($row['published'])?'checked':'' ?>> Pubblicato</label></div><p><button class="btn" type="submit">Salva album</button></p></form><?php if((int)$row['id']): ?><div class="panel"><h2>Aggiungi immagine</h2><form method="post" enctype="multipart/form-data" action="/admin/content/gallery/image"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="album_id" value="<?= (int)$row['id'] ?>"><div class="formgrid"><label>Immagine<input type="file" name="image_file" accept="image/jpeg,image/png,image/webp" required></label><label>Testo alternativo<input name="alt_text"></label><label class="full">Didascalia<input name="caption"></label><label>Ordine<input type="number" name="sort_order" value="0"></label><label class="check"><input type="checkbox" name="published" value="1" checked> Pubblicata</label></div><p><button class="btn" type="submit">Aggiungi immagine</button></p></form></div><h2>Immagini</h2><table><thead><tr><th>Anteprima</th><th>Didascalia</th><th>Ordine</th></tr></thead><tbody><?php foreach($images as $img): ?><tr><td><img src="<?= htmlspecialchars($img['image_path']) ?>" alt="" style="width:90px;height:60px;object-fit:cover"></td><td><?= htmlspecialchars((string)$img['caption']) ?></td><td><?= (int)$img['sort_order'] ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><?php require __DIR__.'/_layout_end.php'; ?>